using System;namespace Recovered.Gameplay {public static class PtlMaterialWrappers {public static uint Allocate(SoundSetupImage m,int count,Func<SoundSetupImage,uint,uint[],uint> service){uint type=m.Word(0x973ff4);return service(m,0x5e4b20,new uint[]{unchecked((uint)count),type,1});}public static void Finalize(SoundSetupImage m,uint material,Func<SoundSetupImage,uint,uint[],uint> service){service(m,0x601030,new uint[]{material});m.Half(material+0x2c0,unchecked((ushort)(m.Half(material+0x2c0)+1)));}public static uint Invoke(SoundSetupImage m,uint address,uint[] args,Func<SoundSetupImage,uint,uint[],uint> service){if(address==0x5e4d40)return Allocate(m,unchecked((int)args[0]),service);if(address==0x5e4b00){Finalize(m,args[0],service);return 0;}return service(m,address,args);}public static uint Create(SoundSetupImage m,uint parent,uint option,uint variant,uint group,uint channel,Func<SoundSetupImage,uint,uint[],uint> service){return PtlMaterialConstruction.Create(m,parent,option,variant,group,channel,delegate(SoundSetupImage image,uint address,uint[] values){return Invoke(image,address,values,service);});}}}
